with base as (select id, full_name, email, dept_id, job_title, salary, hire_date, is_remote, trim(job_title) as clean_job_title, coalesce(level, 'N/A') as level_clean from employees where not is_remote) select *, percent_rank() over (partition by dept_id order by salary desc) as salary_percent_rank, avg(salary) over (partition by dept_id order by hire_date, id rows between 6 preceding and current row) as salary_avg_6 from base
